#include "mgt_cuda/p888_step_control.cuh"

int main(){mgt_cuda::P888StepControlV1* d=nullptr;cudaStream_t s=nullptr;if(cudaMalloc(&d,sizeof(*d))!=cudaSuccess||cudaStreamCreateWithFlags(&s,cudaStreamNonBlocking)!=cudaSuccess)return 1;if(mgt_cuda::InitializeP888StepControl(d,7,11,888)!=mgt::Status::kOk)return 2;mgt_cuda::P888StepControlV1 h{};if(cudaMemcpy(&h,d,sizeof(h),cudaMemcpyDeviceToHost)!=cudaSuccess)return 3;h.active_rows=12500;h.global_rows=100000;h.global_offset=25000;if(cudaMemcpy(d,&h,sizeof(h),cudaMemcpyHostToDevice)!=cudaSuccess)return 4;if(mgt_cuda::LaunchBeginP888StepControl(d,mgt_cuda::A100LocalGraphSlot::kFull,s)!=mgt::Status::kOk||mgt_cuda::LaunchCommitP888StepControl(d,s)!=mgt::Status::kOk||cudaStreamSynchronize(s)!=cudaSuccess||cudaMemcpy(&h,d,sizeof(h),cudaMemcpyDeviceToHost)!=cudaSuccess)return 5;if(h.fatal_health||h.committed_sequence!=8||h.committed_optimizer_step!=12||h.batch_slot!=0)return 6;if(mgt_cuda::LaunchCommitP888StepControl(d,s)!=mgt::Status::kOk||cudaStreamSynchronize(s)!=cudaSuccess||cudaMemcpy(&h,d,sizeof(h),cudaMemcpyDeviceToHost)!=cudaSuccess)return 7;if(h.fatal_health!=(std::uint32_t)mgt_cuda::P888StepFatal::kCommitWithoutInflight)return 8;cudaStreamDestroy(s);cudaFree(d);return 0;}
